// @ts-check
import js from '@eslint/js';
import tseslint from 'typescript-eslint';
import globals from 'globals';
import prettier from 'eslint-config-prettier';

export default tseslint.config(
  {
    ignores: [
      '**/node_modules/**',
      '**/dist/**',
      '**/.next/**',
      '**/coverage/**',
      '**/generated/**',
      'services/document-engine/**',
      // Generated by `next build`; committed so typecheck works before a build.
      '**/next-env.d.ts',
    ],
  },
  js.configs.recommended,
  ...tseslint.configs.recommended,
  {
    /*
     * Generated contract artefacts.
     *
     * They carry a blanket disable because json-schema-to-typescript emits
     * shapes the rules object to — but which rules fire depends on the schema,
     * so for a simple schema the directive is unused and lint complains about
     * the directive itself. The file is machine-written either way, so the
     * check is simply not applied to it: tailoring the banner per schema would
     * mean editing generated output by hand, which is what generating it
     * exists to avoid.
     */
    files: ['**/*.generated.ts', '**/generated.ts'],
    linterOptions: { reportUnusedDisableDirectives: 'off' },
  },
  {
    languageOptions: {
      globals: { ...globals.node },
      parserOptions: { ecmaVersion: 'latest', sourceType: 'module' },
    },
    rules: {
      // Section 46: strict TypeScript, no unnecessary `any`.
      '@typescript-eslint/no-explicit-any': 'error',
      '@typescript-eslint/no-unused-vars': [
        'error',
        { argsIgnorePattern: '^_', varsIgnorePattern: '^_', caughtErrorsIgnorePattern: '^_' },
      ],
      '@typescript-eslint/consistent-type-imports': [
        'error',
        { prefer: 'type-imports', fixStyle: 'inline-type-imports' },
      ],
      // Section 46: no hard-coded secrets / structured logging only.
      'no-console': ['error', { allow: ['warn', 'error'] }],
      eqeqeq: ['error', 'always'],
      'prefer-const': 'error',
    },
  },
  {
    files: ['**/*.spec.ts', '**/*.test.ts', '**/*.e2e-spec.ts', '**/vitest.config.ts'],
    rules: {
      '@typescript-eslint/no-explicit-any': 'off',
      'no-console': 'off',
    },
  },
  {
    // Operator-facing command-line tools. Their entire output is a console
    // transcript an operator reads during a backup or a recovery, so the
    // application's "log through pino, never console" rule does not apply:
    // there is no logger to route through and nobody tailing a log file.
    files: [
      'scripts/**/*.{mjs,cjs}',
      'apps/*/scripts/**/*.{mjs,cjs}',
      'packages/*/scripts/**/*.{mjs,cjs}',
      // The load-fixture describer is the same kind of thing: an operator runs
      // it before a load run and reads what it prints.
      'perf/*.{mjs,cjs}',
    ],
    rules: {
      'no-console': 'off',
      // A `.cjs` module is CommonJS by definition. The backup format module is
      // deliberately CommonJS so the operator tooling and the Jest suite share
      // one implementation instead of two that can drift apart.
      '@typescript-eslint/no-require-imports': 'off',
    },
  },
  {
    // Browser-driving scripts (Phase 20 Checkpoints 7 and 8).
    //
    // `page.evaluate()` takes a function that is serialized and run *inside*
    // the page, where `document`, `window` and `getComputedStyle` exist. ESLint
    // sees them in a Node file and flags them, which is correct about the file
    // and wrong about the function.
    files: ['scripts/security/browser-security.mjs', 'qa/**/*.mjs'],
    languageOptions: {
      globals: {
        document: 'readonly',
        window: 'readonly',
        getComputedStyle: 'readonly',
        location: 'readonly',
        MutationObserver: 'readonly',
      },
    },
    rules: {
      // The QA runner's entire output is a transcript a person reads.
      'no-console': 'off',
    },
  },
  {
    // k6 load scenarios (Phase 20 Checkpoint 6).
    //
    // These run inside k6's own JavaScript runtime, not in Node and not in a
    // browser. It injects three globals — `__ENV` (the environment the run
    // was started with), `__VU` (this virtual user's number) and `__ITER`
    // (this iteration's) — which no Node or browser environment declares, so
    // `no-undef` flags every use of them. They are declared here rather than
    // suppressed inline, because a scenario file is about a dozen lines of
    // logic and would otherwise be mostly eslint comments.
    //
    // `console` is the output: k6 has no logger, and a scenario's diagnostics
    // are read from the run transcript.
    files: ['perf/k6/**/*.js'],
    languageOptions: {
      globals: { __ENV: 'readonly', __VU: 'readonly', __ITER: 'readonly' },
    },
    rules: {
      'no-console': 'off',
    },
  },
  {
    // NestJS resolves constructor dependencies from `emitDecoratorMetadata`,
    // which TypeScript erases for `import type`. Rewriting an injected class
    // import to a type-only import therefore breaks dependency injection at
    // runtime while still type-checking, so the rule is disabled here.
    files: ['apps/api/**/*.ts'],
    rules: {
      '@typescript-eslint/consistent-type-imports': 'off',
      '@typescript-eslint/no-extraneous-class': 'off',
    },
  },
  prettier,
);
